package android.app;
public class FragmentManager { private final java.util.HashMap<String,Fragment> fragments=new java.util.HashMap<String,Fragment>(); public FragmentTransaction beginTransaction() { return new FragmentTransaction(this); } public Fragment findFragmentByTag(String tag) { return fragments.get(tag); } public Fragment findFragmentById(int id) { return fragments.get(String.valueOf(id)); } public boolean executePendingTransactions() { return true; } void add(String tag,Fragment f) { if(tag!=null) fragments.put(tag,f); } void remove(Fragment f) { java.util.ArrayList<String> keys=new java.util.ArrayList<String>(fragments.keySet()); for(String k:keys) if(fragments.get(k)==f) fragments.remove(k); } }
